+        $sort = 0;
+
+        foreach ($tree as $parentName => $children) {
+            $parent = Category::firstOrCreate(
+                ['name' => $parentName, 'parent_id' => null],
+                [
+                    'slug' => SlugService::unique(Category::class, $parentName),
